#!/usr/bin/env node
/**
 * Builds the static demo site into site/dist.
 *
 *   site/dist/index.html          landing + playground
 *   site/dist/assets/*.{js,css}   playground bundle (the real engine) and styles
 *   site/dist/report/index.html   full report generated by the CLI from examples/aurora
 *
 * All URLs are relative, so the site works under any base path
 * (e.g. https://<user>.github.io/tokensync/).
 * Requires `npm run build` first (the report is generated by dist/cli.js).
 */
import { execFileSync } from 'node:child_process';
import { copyFileSync, mkdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { build } from 'esbuild';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const site = resolve(root, 'site');
const out = resolve(site, 'dist');
const aurora = resolve(root, 'examples/aurora');
const read = (p) => readFileSync(resolve(aurora, p), 'utf8');

rmSync(out, { recursive: true, force: true });
mkdirSync(resolve(out, 'assets'), { recursive: true });
mkdirSync(resolve(out, 'report'), { recursive: true });

// 1. Playground bundle: the same engine modules the CLI ships, bundled for browsers.
await build({
  entryPoints: [resolve(site, 'src/playground.ts')],
  outfile: resolve(out, 'assets/playground.js'),
  bundle: true,
  format: 'esm',
  platform: 'browser',
  target: 'es2022',
  minify: true,
  legalComments: 'none',
  define: {
    __AURORA__: JSON.stringify({
      figma: read('figma/variables.json'),
      css: read('src/styles/tokens.css'),
      dtcg: read('tokens/primitives.tokens.json'),
      tailwind: read('tailwind.theme.json'),
    }),
  },
  logLevel: 'warning',
});

// 2. Styles: site CSS + the report's own CSS, so the playground report is pixel-identical.
const { REPORT_CSS } = await import(resolve(root, 'dist/index.js'));
writeFileSync(resolve(out, 'assets/site.css'), `${readFileSync(resolve(site, 'src/site.css'), 'utf8')}\n${REPORT_CSS}`);

// 3. Pages.
copyFileSync(resolve(site, 'index.html'), resolve(out, 'index.html'));
copyFileSync(resolve(site, 'public/favicon.svg'), resolve(out, 'favicon.svg'));
writeFileSync(resolve(out, '.nojekyll'), '');

// 4. Full report, generated by the real CLI from the Aurora example.
execFileSync(
  process.execPath,
  [
    resolve(root, 'dist/cli.js'),
    'report',
    '--config',
    resolve(aurora, 'tokensync.config.json'),
    '--out',
    resolve(out, 'report/index.html'),
  ],
  { cwd: aurora, stdio: 'inherit', env: { ...process.env, NO_COLOR: '1' } },
);

console.log(`Site built in ${out.replace(`${root}/`, '')}`);
